@tool
extends Node

func _walk(base: String, out: Array) -> void:
	var d := DirAccess.open(base if base.begins_with("res://") or base.begins_with("E:/") else "res://" + base)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if not n.begins_with(".godot") and n != "__MACOSX":
			var p := (base + "/" + n) if base != "" else n
			if d.current_is_dir():
				_walk(p, out)
			else:
				out.append(p)
		n = d.get_next()
	d.list_dir_end()

func run() -> String:
	var files: Array = []
	_walk("", files)
	var d := DirAccess.open("res://")
	var removed := 0
	var kept_macosx: Array = []
	var sample: Array = []
	for f in files:
		var fs := String(f)
		var fn := fs.get_file()
		if fn.begins_with("._") or fn == ".DS_Store":
			var err := d.remove(fs)
			if err == OK:
				removed += 1
				if sample.size() < 10:
					sample.append(fs)
			else:
				kept_macosx.append(fs + " err=" + str(err))
	# hunt for the missing gltf bin
	var bin_hits: Array = []
	var proj: Array = []
	_walk("", proj)
	for f in proj:
		if String(f).contains("Decal_Line_90"):
			bin_hits.append("res://" + String(f))
	var q: Array = []
	var dq := DirAccess.open("E:/ghost-company-quarantine")
	if dq != null:
		var q2 := []
		# walk quarantine manually (E: style)
		_qwalk("E:/ghost-company-quarantine", "", q2)
		for f in q2:
			if String(f).contains("Decal_Line_90"):
				bin_hits.append(String(f))
	var decal_dir: Array = []
	var dd := DirAccess.open("res://assets/gltf/Decals")
	if dd != null:
		dd.list_dir_begin()
		var nn := dd.get_next()
		while nn != "":
			decal_dir.append(nn)
			nn = dd.get_next()
	rep := {"apple_junk_removed": removed, "remove_failures": kept_macosx, "samples": sample, "decal_line90_hits": bin_hits, "decals_dir": decal_dir}
	var out := FileAccess.open("res://tools/gc_junk_report.json", FileAccess.WRITE)
	if out != null:
		out.store_string(JSON.stringify(rep))
	return "JUNK removed=" + str(removed) + " fails=" + str(kept_macosx.size()) + " decal_hits=" + str(bin_hits.size())

func _qwalk(root: String, base: String, out: Array) -> void:
	var d := DirAccess.open(root + "/" + base if base != "" else root)
	if d == null:
		return
	d.list_dir_begin()
	var n := d.get_next()
	while n != "":
		if not n.begins_with("."):
			var p := (base + "/" + n) if base != "" else n
			if d.current_is_dir():
				_qwalk(root, p, out)
			else:
				out.append(root + "/" + p)
		n = d.get_next()
	d.list_dir_end()
